'use client';
const require_pagination = require("./pagination.cjs");
const require_pagination_button = require("./pagination-button.cjs");
const require_pagination_item = require("./pagination-item.cjs");
const require_pagination_list = require("./pagination-list.cjs");
//#region src/components/pagination/index.ts
/**
* Pagination component, used to navigate through a list of items.
*
* @example
* <Pagination>
*   <Pagination.List>
*     <Pagination.Item>
*       <Pagination.Button aria-label='Forrige side'>Forrige</Pagination.Button>
*     </Pagination.Item>
*     <Pagination.Item>
*       <Pagination.Button aria-label='Side 1'>1</Pagination.Button>
*     </Pagination.Item>
*     <Pagination.Item>
*       <Pagination.Button aria-label='Side 2'>2</Pagination.Button>
*     </Pagination.Item>
*   </Pagination.List>
* </Pagination>
*/
const PaginationComponent = Object.assign(require_pagination.Pagination, {
	List: require_pagination_list.PaginationList,
	Item: require_pagination_item.PaginationItem,
	Button: require_pagination_button.PaginationButton
});
PaginationComponent.List.displayName = "Pagination.List";
PaginationComponent.Item.displayName = "Pagination.Item";
PaginationComponent.Button.displayName = "Pagination.Button";
//#endregion
exports.Pagination = PaginationComponent;
exports.PaginationButton = require_pagination_button.PaginationButton;
exports.PaginationItem = require_pagination_item.PaginationItem;
exports.PaginationList = require_pagination_list.PaginationList;
